import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  uniqueIndex,
} from "drizzle-orm/pg-core";

import { LEAD_STATUSES } from "@/config/leads";

import { createdAt, id, instant, timestamps, version } from "../columns";

/**
 * Tables that exist in every project (04-veri §10). Auth tables are generated by the
 * Better Auth CLI into ./auth.ts. Feature tables live in their own files.
 */

/** Single-row, versioned site configuration edited from the panel (white-label). */
export const siteSettings = pgTable(
  "site_settings",
  {
    id: text().primaryKey().default("singleton"),
    company: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    contact: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    openingHours: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    social: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    theme: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    features: jsonb().$type<Record<string, boolean>>().notNull().default({}),
    seo: jsonb().$type<Record<string, unknown>>().notNull().default({}),
    // P-08 price display (K-05): hidden ("contact") unless the owner turns it on.
    pricing: jsonb().$type<Record<string, unknown>>().notNull().default({ display: "contact" }),
    maintenanceMode: boolean().notNull().default(false),
    ...version,
    ...timestamps,
  },
  (table) => [check("ck_site_settings_singleton", sql`${table.id} = 'singleton'`)],
);

/** Every form submission lands here (talep kutusu, Z-29). */
export const leads = pgTable(
  "leads",
  {
    id: id(),
    code: text().notNull(),
    kind: text().notNull(), // contact, quote, callback, appointmentRequest…
    status: text({ enum: LEAD_STATUSES }).notNull().default("new"),
    name: text().notNull(),
    phone: text(), // E.164
    email: text(),
    message: text(),
    preferredChannel: text(),
    sourcePath: text(),
    utm: jsonb().$type<Record<string, string>>(),
    assigneeId: text(),
    note: text(),
    readAt: instant(),
    ...timestamps,
  },
  (table) => [
    uniqueIndex("ux_leads_code").on(table.code),
    index("ix_leads_status_created_at").on(table.status, table.createdAt),
    check(
      "ck_leads_status",
      sql`${table.status} in (${sql.raw(LEAD_STATUSES.map((s) => `'${s}'`).join(", "))})`,
    ),
  ],
);

/** Append-only consent log with the text version (10-yasal-ve-kvkk §4). */
export const consentRecords = pgTable(
  "consent_records",
  {
    id: id(),
    kind: text().notNull(),
    granted: boolean().notNull(),
    textVersion: text().notNull(),
    source: text().notNull(),
    subjectRef: text().notNull(),
    ipHash: text(),
    ...createdAt,
  },
  (table) => [
    index("ix_consent_records_subject").on(table.subjectRef, table.kind, table.createdAt),
  ],
);

/** Messages that would have been sent while DEMO_MODE=true (02-mimari §5). */
export const demoOutbox = pgTable("demo_outbox", {
  id: id(),
  channel: text().notNull(),
  to: text().notNull(),
  template: text().notNull(),
  data: jsonb().$type<Record<string, unknown>>().notNull(),
  relatedId: text(),
  ...createdAt,
});

/** Fixed-window counters for action rate limits (11-guvenlik §9). Auth has its own limiter. */
export const actionRateLimits = pgTable("action_rate_limits", {
  key: text().primaryKey(),
  count: integer().notNull().default(0),
  expiresAt: instant().notNull(),
});

/** Who changed what (S3+, or S2 with several panel users). */
export const auditLogs = pgTable(
  "audit_logs",
  {
    id: id(),
    actorId: text(),
    action: text().notNull(), // appointments.confirm, settings.edit, auth.login.failed…
    entity: text(),
    entityId: text(),
    changes: jsonb().$type<Record<string, { from: unknown; to: unknown }>>(),
    ipHash: text(),
    ...createdAt,
  },
  (table) => [index("ix_audit_logs_entity").on(table.entity, table.entityId, table.createdAt)],
);
